import {
  IdentifierArray,
  SUI_MAINNET_CHAIN,
  SUI_TESTNET_CHAIN,
  StandardConnectFeature,
  StandardEventsFeature,
  SuiFeatures,
  SuiSignTransactionBlockInput,
  Wallet,
  WalletAccount,
} from "@mysten/wallet-standard";
import { Bellhop } from "./Bellhop";
import { TransactionType } from "@msafe/sui3-utils";

export type SuiNetworks =
  | "sui:devnet"
  | "sui:testnet"
  | "sui:localnet"
  | "sui:mainnet";

export interface WalletMessage {
  type: string;
  content: any;
}

export interface WalletMessageListener {
  onMessage(message: WalletMessage): void;
}

export interface OnAccountChangeListner {
  onAccountChange(account: WalletAccount): void;
}

export interface ProposeIntentionMessage {
  application: string;
  txType: TransactionType;
  txSubType: string;
  intentionData: any;
}

export interface ProposeTransactionMessage
  extends SuiSignTransactionBlockInput {
  application: string;
  account: WalletAccount;
  clientUrl: string;
  network: SuiNetworks;
  isTransaction: true;
  transactionBlockSerialize: string;
}

export interface MSafeWalletServerApi {
  connect(): Promise<WalletAccount[]>;
  proposeIntention(input: ProposeTransactionMessage): Promise<void>;
}

export class MSafeWalletServer {
  private bellhop = new Bellhop();

  constructor(iframe: HTMLIFrameElement, walletApi: MSafeWalletServerApi) {
    this.bellhop.connect(iframe);
    this.bellhop.on("connect", async () => {
      const account = await walletApi.connect();
      this.bellhop.respond("account", account);
    });
    this.bellhop.on("proposeIntention", async (data: any) => {
      await walletApi.proposeIntention(data.data);
    });
  }

  public sendMessage(message: WalletMessage) {
    this.bellhop.send("walletMessage", message);
  }

  public cancelProposeIntention() {
    this.bellhop.send("cancel");
  }

  public changeAccount(account: WalletAccount) {
    this.bellhop.send("accountChange", account);
  }
}

export class MSafeWallet implements Wallet {
  accounts: WalletAccount[] = [];

  private currentAccount: WalletAccount;
  private bellhop = new Bellhop();
  private walletMessageListener: WalletMessageListener;
  private onAccountChangeListner: OnAccountChangeListner;

  public readonly version = "1.0.0";
  public readonly name = "MSafe Wallet";
  public readonly icon =
    "data:image/svg+xml;base64,";
  public readonly chains = [
    SUI_MAINNET_CHAIN,
    SUI_TESTNET_CHAIN,
  ] as IdentifierArray;

  constructor(
    private appName: string,
    private clientUrl: string,
    private network: SuiNetworks
  ) {
    this.bellhop.connect();
    this.bellhop.on("walletMessage", async (data: any) => {
      if (this.walletMessageListener) {
        this.walletMessageListener.onMessage(data.data);
      }
    });
    this.bellhop.on("accountChange", async (data: any) => {
      this.currentAccount = data.data;
      if (this.onAccountChangeListner) {
        this.onAccountChangeListner.onAccountChange(this.currentAccount);
      }
    });
  }

  public setWalletMessageListener(listener: WalletMessageListener) {
    this.walletMessageListener = listener;
  }

  public setOnAccountChangeListener(listener: OnAccountChangeListner) {
    this.onAccountChangeListner = listener;
  }

  public static inMSafeWallet(): boolean {
    return (
      typeof window !== "undefined" &&
      typeof document !== "undefined" &&
      typeof parent !== "undefined" &&
      typeof parent.window !== "undefined" &&
      parent.window !== window
    );
  }

  public readonly features: StandardConnectFeature &
    StandardEventsFeature &
    SuiFeatures = {
    "standard:connect": {
      version: "1.0.0",
      connect: async () => {
        this.bellhop.send("connect");
        const accounts = await this.fetch<WalletAccount[]>("account");
        this.accounts = accounts;
        if (accounts.length > 0) {
          this.currentAccount = accounts[0];
        }
        return {
          accounts,
        };
      },
    },
    "standard:events": {
      version: "1.0.0",
      on: (e) => {
        return () => {};
      },
    },
    "sui:signMessage": {
      version: "1.0.0",
      signMessage: async () => {
        throw new Error("No impl");
      },
    },
    "sui:signPersonalMessage": {
      version: "1.0.0",
      signPersonalMessage: async () => {
        throw new Error("No impl");
      },
    },
    "sui:signTransactionBlock": {
      version: "1.0.0",
      signTransactionBlock: async (input) => {
        return this.proposeIntention(input);
      },
    },
    "sui:signAndExecuteTransactionBlock": {
      version: "1.0.0",
      signAndExecuteTransactionBlock: async (input) => {
        return this.proposeIntention(input);
      },
    },
  };

  private async proposeIntention<T>(input: SuiSignTransactionBlockInput) {
    if (!this.currentAccount) {
      throw new Error("Wallet not connected");
    }
    const parseTransaction = input.transactionBlock.serialize();

    this.bellhop.send("proposeIntention", {
      application: this.appName,
      ...input,
      transactionBlockSerialize: parseTransaction,
      clientUrl: this.clientUrl,
      network: this.network,
      account: this.currentAccount,
      isTransaction: true,
    } as ProposeTransactionMessage);

    let cancel: (reasion: string) => void;
    this.bellhop.on("cancel", async () => {
      if (cancel) {
        cancel("User canceled");
      }
    });

    const result = new Promise<T>((_, reject) => {
      cancel = reject;
    });

    return result;
  }

  private async fetch<T>(name: string) {
    return new Promise<T>((resolve) => {
      this.bellhop.fetch(name, (data: any) => {
        resolve(data.data);
      });
    });
  }
}
